@layer ui-sdk;
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

:root {
  --background: var(--color-zinc-50);
  --foreground: var(--color-zinc-950);
  --surface: var(--color-white);
  --surface-raised: var(--color-white);
  --sidebar: var(--color-zinc-50);
  --muted: var(--color-zinc-100);
  --muted-foreground: var(--color-zinc-500);
  --subtle-foreground: var(--color-zinc-400);
  --accent: var(--color-zinc-100);
  --accent-foreground: var(--color-zinc-900);
  --border: var(--color-zinc-200);
  --border-strong: var(--color-zinc-300);
  --input: var(--color-zinc-200);
  --ring: var(--color-zinc-400);
  --primary: var(--color-zinc-900);
  --primary-foreground: var(--color-zinc-50);
  --destructive: var(--color-red-600);
  --success: var(--color-emerald-600);
  --drop: color-mix(in oklab, var(--color-zinc-500) 12%, transparent);
  --drop-border: color-mix(in oklab, var(--color-zinc-500) 55%, transparent);
  --shadow-color: color-mix(in oklab, var(--color-zinc-950) 8%, transparent);

  --radius: 8px;
  --titlebar-height: 40px;
  --tabbar-height: 34px;
  --control-height: 32px;
  --control-height-sm: 28px;
}

.dark {
  --background: var(--color-zinc-950);
  --foreground: var(--color-zinc-50);
  --surface: var(--color-zinc-900);
  --surface-raised: var(--color-zinc-900);
  --sidebar: var(--color-zinc-950);
  --muted: var(--color-zinc-800);
  --muted-foreground: var(--color-zinc-400);
  --subtle-foreground: var(--color-zinc-500);
  --accent: var(--color-zinc-800);
  --accent-foreground: var(--color-zinc-50);
  --border: var(--color-zinc-800);
  --border-strong: var(--color-zinc-700);
  --input: var(--color-zinc-800);
  --ring: var(--color-zinc-500);
  --primary: var(--color-zinc-50);
  --primary-foreground: var(--color-zinc-900);
  --destructive: var(--color-red-500);
  --success: var(--color-emerald-500);
  --drop: color-mix(in oklab, var(--color-zinc-400) 12%, transparent);
  --drop-border: color-mix(in oklab, var(--color-zinc-400) 55%, transparent);
  --shadow-color: color-mix(in oklab, black 45%, transparent);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-surface-raised: var(--surface-raised);
  --color-sidebar: var(--sidebar);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-subtle-foreground: var(--subtle-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-destructive: var(--destructive);
  --color-success: var(--success);
  --color-drop: var(--drop);
  --color-drop-border: var(--drop-border);

  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 4px);
  --radius-xl: calc(var(--radius) + 8px);

  --text-2xs: 11px;
  --text-2xs--line-height: 16px;
  --text-xs: 12px;
  --text-xs--line-height: 16px;
  --text-ui: 13px;
  --text-ui--line-height: 18px;
  --text-sm: 14px;
  --text-sm--line-height: 20px;
  --text-base: 15px;
  --text-base--line-height: 24px;

  --spacing-titlebar: var(--titlebar-height);
  --spacing-tabbar: var(--tabbar-height);
  --spacing-control: var(--control-height);
  --spacing-control-sm: var(--control-height-sm);

  --shadow-popover: 0 0 0 1px var(--border), 0 8px 24px -6px var(--shadow-color), 0 2px 6px -2px var(--shadow-color);

  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;
}

@layer base {
  *,
  ::before,
  ::after {
    border-color: var(--border);
  }

  html,
  body,
  #root {
    height: 100%;
  }

  body {
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: var(--text-ui);
    line-height: var(--text-ui--line-height);
    -webkit-font-smoothing: antialiased;
    overflow: hidden;
  }

  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 1px;
  }

  ::selection {
    background: color-mix(in oklab, var(--color-zinc-500) 25%, transparent);
  }
}
